/**
 * The 32 one-mail commands, one wrapper each.
 *
 * Names, parameters and return types are frozen: the page hook and every
 * one-mail component are written against this module, and the command strings
 * must stay in step with `src-tauri/one-mail-core/src/commands.rs`,
 * `src-tauri/src/invoke.rs`, `src-tauri/build.rs`, `capabilities/default.json`
 * and `permissions/autogenerated/one_mail_*.toml`.
 */

import { invokeCommand } from "../../base";
import type {
  AccountInput,
  AccountSummary,
  AccountTestInput,
  AccountUpdateInput,
  ConnectionTestResult,
  ConversationMessagesQuery,
  ConversationPage,
  ConversationQuery,
  ConversationThread,
  Draft,
  DraftInput,
  FolderCandidate,
  FolderDiscoveryInput,
  MailFolder,
  MessageBodyLoad,
  MessageDetail,
  MessageSearchPage,
  MessageSummary,
  OneMailSettings,
  OutboxItem,
  PickedAttachment,
  ProviderPreset,
  RawMessage,
  SearchQuery,
  SendInput,
  SendResult,
  SyncInput,
  SyncReport,
  SyncStatus,
} from "./types";

const EMPTY = {} as Record<string, never>;

export async function oneMailProvidersList(): Promise<ProviderPreset[]> {
  return await invokeCommand<Record<string, never>, ProviderPreset[]>(
    "one_mail_providers_list",
    EMPTY
  );
}

export async function oneMailAccountsList(): Promise<AccountSummary[]> {
  return await invokeCommand<Record<string, never>, AccountSummary[]>(
    "one_mail_accounts_list",
    EMPTY
  );
}

export async function oneMailAccountCreate(input: AccountInput): Promise<AccountSummary> {
  return await invokeCommand<{ input: AccountInput }, AccountSummary>("one_mail_account_create", {
    input,
  });
}

export async function oneMailAccountUpdate(input: AccountUpdateInput): Promise<AccountSummary> {
  return await invokeCommand<{ input: AccountUpdateInput }, AccountSummary>(
    "one_mail_account_update",
    { input }
  );
}

export async function oneMailAccountRemove(accountId: number): Promise<boolean> {
  return await invokeCommand<{ accountId: number }, boolean>("one_mail_account_remove", {
    accountId,
  });
}

export async function oneMailAccountTest(input: AccountTestInput): Promise<ConnectionTestResult> {
  return await invokeCommand<{ input: AccountTestInput }, ConnectionTestResult>(
    "one_mail_account_test",
    { input }
  );
}

